#[test]
fn test_a_language_cell_unpacks_to_its_letters() {
    let out: &mut crate::port::Cells = &mut crate::port::Cells::new();
    crate::testport::assert_eq(sk_unpack(1701734144, out), 3, "`eng` is three letters");
    crate::testport::assert_eq(crate::port::cells_at(out, 0), 101, "e");
    crate::testport::assert_eq(crate::port::cells_at(out, 2), 103, "g");
    crate::testport::assert_eq(sk_unpack(0, out), 0, "none");
}
#[test]
fn test_a_script_no_model_read_is_unread() {
    // Deva 1147500129, Latn 1281455214, Cyrl 1132032620; the languages `eng` 1701734144, `hin` 1751739904, `rus` 1920299776
    crate::testport::assert_eq(unread_of(5, 1147500129, 629, 1701734144, 1701734144), 1, "a Devanagari page (OSD 62.9) read by `eng`: unread (the smoke review's Hindi scan)");
    crate::testport::assert_eq(unread_of(5, 1132032620, 400, 1701734144, 1701734144), 1, "a Cyrillic page read by `eng`: unread");
    crate::testport::assert_eq(unread_of(5, 1147500129, 629, 1751739904, 1751739904), 0, "the same read by `hin`, which reads Devanagari: read");
    crate::testport::assert_eq(unread_of(5, 1147500129, 629, 1701734144, 1751739904), 0, "one word read by `hin` is a model that reads it: read");
    crate::testport::assert_eq(unread_of(5, 1132032620, 400, 1920299776, 1920299776), 0, "a Cyrillic page read by `rus`: read");
    crate::testport::assert_eq(unread_of(5, 1147500129, 629, 1920299776, 1920299776), 1, "a Devanagari page read by `rus` (which reads Cyrillic): unread");
}
#[test]
fn test_a_page_the_engine_can_read_or_osd_is_unsure_of_is_not_flagged() {
    crate::testport::assert_eq(unread_of(5, 1281455214, 629, 1701734144, 1701734144), 0, "a Latin page");
    crate::testport::assert_eq(unread_of_d(5, 1147500129, 100, 1701734144, 1701734144, 1), 0, "OSD unsure (confidence 10: a Latin page reads that) and the engine's dictionary knows the words: Latin");
    crate::testport::assert_eq(unread_of_d(5, 1147500129, sk_min_conf() - 1, 1701734144, 1701734144, 1), 0, "just under the bound, the words known");
    crate::testport::assert_eq(unread_of_d(5, 1147500129, sk_min_conf(), 1701734144, 1701734144, 1), 1, "at it: believed whatever the dictionary says (the page of the smoke review)");
    crate::testport::assert_eq(unread_of(5, 1147500129, sk_weak_conf(), 1701734144, 1701734144), 1, "R2: OSD at 5.0 and none of the words known (Urdu, Han, Ethiopic in a Latin model): unread");
    crate::testport::assert_eq(unread_of(5, 1147500129, sk_weak_conf() - 1, 1701734144, 1701734144), 0, "under 5.0: OSD says nothing");
    crate::testport::assert_eq(unread_of(2, 1147500129, 629, 1701734144, 1701734144), 0, "two words: the engine read nothing of it to speak of");
    crate::testport::assert_eq(unread_of(5, 0, 629, 1701734144, 1701734144), 0, "no script");
}
